class QueryAlgebraBindingAnalysisValuesTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void valuesFactsAgreeWithIndependentColumnOracle() {
		Value iri = VF.createIRI("urn:i");
		Value blank = VF.createBNode("b");
		Value one = VF.createLiteral("1", XSD.INTEGER);
		Value padded = VF.createLiteral("01", XSD.INTEGER);
		Value triple = VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"), one);
		Map<Value, ValueKind> terms = Map.of(iri, ValueKind.IRI, blank, ValueKind.BNODE, one, ValueKind.LITERAL,
				padded, ValueKind.LITERAL, triple, ValueKind.TRIPLE);
		List<String> columns = List.of("iri", "blank", "lexical", "triple", "mixed", "nullable", "gap", "late");
		List<Map<String, Value>> fixture = new ArrayList<>();
		for (int i = 0; i < 3; i++) {
			Map<String, Value> row = new LinkedHashMap<>();
			row.put("iri", iri);
			row.put("blank", blank);
			row.put("lexical", i == 0 ? one : padded);
			row.put("triple", triple);
			row.put("mixed", i == 1 ? blank : iri);
			row.put("nullable", null);
			if (i != 1) {
				row.put("gap", one);
			}
			if (i > 0) {
				row.put("late", iri);
			}
			fixture.add(row);
		}
		fixture.add(fixture.getLast());
		checkFacts(fixture, columns, terms);
		Random seeded = new Random(0x6498);
		Value[] pool = { iri, blank, one, padded, triple };
		for (int sample = 0; sample < 250; sample++) {
			List<Map<String, Value>> rows = new ArrayList<>();
			int size = seeded.nextInt(16);
			for (int i = 0; i < size; i++) {
				if (!rows.isEmpty() && seeded.nextInt(5) == 0) {
					rows.add(rows.get(seeded.nextInt(rows.size())));
				} else {
					Map<String, Value> row = new LinkedHashMap<>();
					for (String column : columns) {
						int state = seeded.nextInt(pool.length + 2);
						if (state == 1) {
							row.put(column, null);
						} else if (state > 1) {
							row.put(column, pool[state - 2]);
						}
					}
					rows.add(row);
				}
			}
			checkFacts(rows, columns, terms);
		}
	}

	@Test
	void valuesAnalysisDoesNotOpenAnArbitrarySource() {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("declared"));
		assignment.setBindingSets(() -> {
			throw new AssertionError("opened an arbitrary potentially one-shot source");
		});
		OutputFacts facts = analyze(assignment);
		assertThat(facts.possibleOutputsKnown()).isFalse();
		assertThat(facts.guaranteedOutputsKnown()).isFalse();
		assertThat(facts.fixedValues()).isEmpty();
		assertThat(facts.canProduceRows()).isTrue();
	}

	@Test
	void equalsUsesFirstTermInObservationOrderAndStillThrowsAfterVariation() {
		List<String> seen = new ArrayList<>();
		RuntimeException late = new IllegalStateException("late equals");
		Value first = new SimpleLiteral("first") {
			@Override
			public boolean equals(Object other) {
				String value = ((Value) other).stringValue();
				seen.add("equals:" + value);
				if (value.equals("throw")) {
					throw late;
				}
				return super.equals(other);
			}
		};
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(List.of(
				new ObservedRow(Map.of("x", first), name -> seen.add("read:first:" + name)),
				new ObservedRow(Map.of("x", VF.createLiteral("different")), name -> seen.add("read:second:" + name)),
				new ObservedRow(Map.of("x", VF.createLiteral("first")), name -> seen.add("read:third:" + name)),
				new ObservedRow(Map.of("x", VF.createLiteral("throw")), name -> seen.add("read:fourth:" + name)),
				new ObservedRow(Map.of("x", VF.createLiteral("unreached")), name -> seen.add("read:last:" + name))));
		assertSame(late, assertThrows(IllegalStateException.class, () -> analyze(assignment)));
		assertThat(seen).containsExactly("read:first:x", "read:second:x", "equals:different", "read:third:x",
				"equals:first", "read:fourth:x", "equals:throw");
	}

	private static void checkFacts(List<Map<String, Value>> rows, List<String> names, Map<Value, ValueKind> terms) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(rows.stream().<BindingSet>map(row -> new ObservedRow(row, ignored -> {
		})).toList());
		OutputFacts facts = analyze(assignment);
		assertThat(facts.possibleOutputsKnown()).isTrue();
		assertThat(facts.guaranteedOutputsKnown()).isTrue();
		assertThat(facts.canProduceRows()).isEqualTo(!rows.isEmpty());
		Set<String> possible = new HashSet<>();
		Set<String> guaranteed = new HashSet<>();
		Map<String, Value> fixed = new HashMap<>();
		Map<String, Set<ValueKind>> kinds = new HashMap<>();
		for (String name : names) {
			var column = rows.stream().map(row -> row.get(name)).toList();
			if (column.stream().anyMatch(value -> value != null)) {
				possible.add(name);
				if (column.stream().noneMatch(value -> value == null)) {
					guaranteed.add(name);
					Value first = column.getFirst();
					if (column.stream().allMatch(first::equals)) {
						fixed.put(name, first);
						kinds.put(name, Set.of(terms.get(first)));
					}
				}
			}
		}
		assertThat(facts.possibleOutputs()).isEqualTo(possible);
		assertThat(facts.guaranteedOutputs()).isEqualTo(guaranteed);
		assertThat(facts.fixedValues()).isEqualTo(fixed);
		assertThat(facts.valueKinds()).isEqualTo(kinds);
	}

	private static OutputFacts analyze(BindingSetAssignment input) {
		return QueryAlgebraBindingAnalysis.withGuaranteedInputNames(input, Set.of()).outputFacts(input);
	}

	private static final class ObservedRow extends MapBindingSet {
		private final Map<String, Value> slots;
		private final Consumer<String> observation;

		private ObservedRow(Map<String, Value> slots, Consumer<String> observation) {
			this.slots = slots;
			this.observation = observation;
			slots.forEach((name, value) -> {
				if (value != null) {
					addBinding(name, value);
				}
			});
		}

		@Override
		public Set<String> getBindingNames() {
			return slots.keySet();
		}

		@Override
		public Value getValue(String name) {
			observation.accept(name);
			return slots.get(name);
		}
	}
}
